// zinc:gl (ZN-562): WebGL 1 and 2 for compiled Zinc code. The calls go straight to the engine's WebGL implementation (src/gl: the WebGL1 class, the
// same validation as the QuickJS binding), with no JS engine and no boxing; a context draws offscreen and `present(image)` copies its pixels into a
// zinc:gfx image (createImage), which the program draws like any other. docs/guide/03-ui-apps.md says how it differs from WebGL in a browser.
// The methods and the host rows they call are generated by tools/gen-zinc-gl; the constants (every WebGL 1 and 2 constant, from src/gl/webgl_consts.inc
// and webgl2_consts.inc) are getters, as a class holds at most 255 fields.

/** What WebGL takes as typed arrays: a Zinc array and the element type the engine converts it to (1 Int8, 2 Uint8, 3 Int16, 4 Uint16, 5 Int32, 6 Uint32,
 *  7 Float32). readPixels and getBufferSubData write into `data`, which must already have the length they fill. */
export class GLArray { constructor(public data: number[], readonly kind: i32) {} }
export class Int8Array extends GLArray { constructor(data: number[]) { super(data, 1); } }
export class Uint8Array extends GLArray { constructor(data: number[]) { super(data, 2); } }
export class Uint8ClampedArray extends GLArray { constructor(data: number[]) { super(data, 2); } }
export class Int16Array extends GLArray { constructor(data: number[]) { super(data, 3); } }
export class Uint16Array extends GLArray { constructor(data: number[]) { super(data, 4); } }
export class Int32Array extends GLArray { constructor(data: number[]) { super(data, 5); } }
export class Uint32Array extends GLArray { constructor(data: number[]) { super(data, 6); } }
export class Float32Array extends GLArray { constructor(data: number[]) { super(data, 7); } }

export class WebGLBuffer { constructor(readonly id: i32) {} }
export class WebGLShader { constructor(readonly id: i32) {} }
export class WebGLProgram { constructor(readonly id: i32) {} }
export class WebGLTexture { constructor(readonly id: i32) {} }
export class WebGLFramebuffer { constructor(readonly id: i32) {} }
export class WebGLRenderbuffer { constructor(readonly id: i32) {} }
export class WebGLVertexArrayObject { constructor(readonly id: i32) {} }
export class WebGLSampler { constructor(readonly id: i32) {} }
export class WebGLQuery { constructor(readonly id: i32) {} }
export class WebGLSync { constructor(readonly id: i32) {} }
export class WebGLTransformFeedback { constructor(readonly id: i32) {} }
export class WebGLUniformLocation { constructor(readonly id: i32) {} }

/** What getParameter and the other queries return, typed: kind 'b' boolean, 'i' integer, 'f' float, 'a' numbers, 's' text, 'o' an object (its id and
 *  kind), 'n' null (an error, or nothing bound). */
export class GLParam {
  constructor(readonly kind: string, readonly numbers: number[], readonly text: string, readonly object: i32, readonly objectKind: i32) {}
  get number(): number { return this.numbers.length > 0 ? this.numbers[0] : 0; }
  get bool(): boolean { return this.number !== 0; }
  get isNull(): boolean { return this.kind === 'n'; }
}
export class WebGLActiveInfo { constructor(readonly size: i32, readonly type: u32, readonly name: string) {} }
export class WebGLShaderPrecisionFormat { constructor(readonly rangeMin: i32, readonly rangeMax: i32, readonly precision: i32) {} }
export class WebGLContextAttributes {
  alpha: boolean = true;
  depth: boolean = true;
  stencil: boolean = false;
  antialias: boolean = false;   // the offscreen target is not multisampled
  premultipliedAlpha: boolean = true;
  preserveDrawingBuffer: boolean = false;
  failIfMajorPerformanceCaveat: boolean = false;
  bits(): i32 { return (this.alpha ? 1 : 0) | (this.depth ? 2 : 0) | (this.stencil ? 4 : 0) | (this.premultipliedAlpha ? 8 : 0) | (this.preserveDrawingBuffer ? 16 : 0); }
  static of(bits: i32): WebGLContextAttributes {
    const a = new WebGLContextAttributes();
    a.alpha = (bits & 1) !== 0; a.depth = (bits & 2) !== 0; a.stencil = (bits & 4) !== 0; a.premultipliedAlpha = (bits & 8) !== 0; a.preserveDrawingBuffer = (bits & 16) !== 0;
    return a;
  }
}

function words(s: string): string[] {
  const out: string[] = [];
  for (const w of s.split(' ')) if (w !== '') out.push(w);
  return out;
}

